command:
(async () => {
  // 兼容讀取 DAE 上下文（args[1]/args[3]/lastArg）
  const hook = args[0];
  const context = args[3] ?? args[1] ?? (args[args.length - 1] && args[args.length - 1].lastArg) ?? null;
  if (!context) return ui.notifications.error("無法取得 DAE 上下文 (args)。");

  // 解析目標 actor/token
  const tgtUuid = context.actorUuid ?? context.tokenUuid ?? null;
  const tgtDoc = tgtUuid ? await fromUuid(tgtUuid).catch(()=>null) : null;
  const targetActor = tgtDoc?.actor ?? tgtDoc ?? game.actors.get(context.actorId) ?? canvas.tokens.get(context.tokenId)?.actor;
  const targetToken = canvas.tokens.get(context.tokenId) ?? (tgtDoc?.token ?? canvas.tokens.placeables.find(t => t.actor?.id === targetActor?.id));
  if (!targetActor) return ui.notifications.error("無法解析目標 actor / token。");

  // 解析施法者 actor 和 token（從 origin 推出）
  const origin = context.origin ?? null; // 例如 "Actor.X.Item.Y.ActiveEffect.Z" 或 "Compendium..."
  const sourceActorUuid = origin ? origin.split(".Item.")[0] : null;
  const sourceDoc = sourceActorUuid ? await fromUuid(sourceActorUuid).catch(()=>null) : null;
  const sourceActor = sourceDoc ? (sourceDoc.actor ?? sourceDoc) : null;
  const sourceToken = canvas.tokens.placeables.find(t => t.actor?.id === sourceActor?.id) ?? null;

  // 如果是刪除時不做事
  if (hook === "off") return;

  // ===== 排除施法者 =====
  // 如果找到了施法者且目標就是施法者，則跳過（不進行豁免）
  if (sourceActor && sourceActor.id && targetActor.id && sourceActor.id === targetActor.id) {
    console.log("跳過施法者 (aura origin) 對自身的豁免/效果：", sourceActor.name);
    return;
  }
  // 額外排除基於 token 的相等判斷（更保險）
  if (sourceToken && targetToken && sourceToken.id === targetToken.id) {
    console.log("跳過施法者 token (aura) 對自身的豁免/效果：", sourceToken.name);
    return;
  }

  // ===== 計算施法者 DC（優先 spelldc，否則 8 + prof + ability mod） =====
  let dc = sourceActor?.system?.attributes?.spelldc?.value ?? sourceActor?.system?.attributes?.spelldc ?? null;
  if (!dc) {
    // 嘗試從 origin item 推斷施法能力
    let itemAbility = null;
    try {
      const originItemUuid = origin ? origin.split(".ActiveEffect")[0] : null;
      if (originItemUuid) {
        const originItemWrapper = await fromUuid(originItemUuid).catch(()=>null);
        const originItem = originItemWrapper?.item ?? originItemWrapper;
        itemAbility = originItem?.system?.ability ?? originItem?.system?.save?.ability ?? originItem?.system?.spellcasting ?? null;
      }
    } catch(e){ /* ignore */ }

    const rollData = (typeof sourceActor?.getRollData === "function") ? sourceActor.getRollData() : (sourceActor?.system ?? {});
    const prof = rollData?.prof ?? rollData?.attributes?.prof ?? 0;
    let abilityMod = 0;
    if (itemAbility && rollData?.abilities?.[itemAbility]) abilityMod = rollData.abilities[itemAbility].mod ?? 0;
    else abilityMod = (rollData?.abilities?.cha?.mod ?? rollData?.abilities?.int?.mod ?? rollData?.abilities?.wis?.mod ?? 0);
    dc = 8 + (prof || 0) + (abilityMod || 0);
  }
  dc = Number(dc);

  // ===== 讓目標進行“感知豁免” (Wis save)。如果你想改爲感知技能 (Perception)，改 rollSkill("perception") =====
  const save = await targetActor.rollAbilitySave("wis", { flavor: `感知豁免 — DC ${dc}` });
  const saveTotal = save?.total ?? 0;
  console.log(`${targetActor.name} 感知豁免: ${saveTotal} vs DC ${dc}`);

  if (saveTotal >= dc) {
    // 豁免成功：無事發生
    ChatMessage.create({ content: `${targetActor.name} 豁免成功（${saveTotal} >= ${dc}），未受到恐慌效果。`, speaker: ChatMessage.getSpeaker({actor: targetActor}) });
    return;
  }

  // ===== 豁免失敗：從 origin 的物品上覆制名爲 "恐慌" 的 effect 到目標上 =====
  if (!origin) {
    ui.notifications.warn("豁免失敗，但未找到 origin，無法從來源物品複製“恐慌”效果。");
    return;
  }
  const originItemUuid = origin.split(".ActiveEffect")[0];
  let originItemDoc = null;
  try { originItemDoc = await fromUuid(originItemUuid).catch(()=>null); } catch(e) { originItemDoc = null; }
  if (!originItemDoc) {
    ui.notifications.warn("未能讀取來源物品（origin）。無法應用“恐慌”效果。");
    return;
  }
  const originItem = originItemDoc?.item ?? originItemDoc;
  const effectsList = originItem?.effects ?? originItem?.data?.effects ?? originItem?.system?.effects ?? null;
  if (!effectsList || effectsList.length === 0) {
    ui.notifications.warn(`來源物品 "${originItem?.name ?? ''}" 未包含任何 Active Effect，無法找到“恐慌”。`);
    return;
  }

  // 查找名爲 "恐慌" 的 effect（完全匹配）
  let panicEffect = null;
  for (const e of effectsList) {
    const nm = e?.label ?? e?.name ?? e?.data?.label ?? e?.data?.name ?? null;
    if (nm === "恐慌") { panicEffect = e; break; }
  }
  if (!panicEffect) {
    ui.notifications.warn(`在來源物品 "${originItem?.name ?? ''}" 上未找到名爲 "恐慌" 的效果。請確認名稱完全匹配。`);
    return;
  }

  // 複製 effect 數據並在目標上創建
  const effectData = panicEffect.toObject ? panicEffect.toObject() : duplicate(panicEffect);
  effectData.origin = origin; // 標記來源
  // 如需可在此調整 flags、transfer 等字段（按需）
  try {
    await targetActor.createEmbeddedDocuments("ActiveEffect", [effectData]);
    ChatMessage.create({ content: `${targetActor.name} 豁免失敗：已受到來自 ${originItem?.name ?? '來源'} 的“恐慌”效果。`, speaker: ChatMessage.getSpeaker({actor: targetActor}) });
  } catch (err) {
    console.error("將“恐慌”效果創建到目標失敗：", err);
    ui.notifications.error("將“恐慌”效果應用到目標時出錯（查看控制檯）。");
  }
})();
